arguments.argument:
var imp;
imp = instance_create(x,y,Impact);
// Make the impact effect occur in the general direction of the stab, far enough from the spy to be noticable
imp.x += sign(cos(degtorad(direction)))*15;
imp.y -= 12;
imp.image_angle = direction;
if (ownerPlayer.object != -1 and instance_exists(ownerPlayer.object)) {
    if (numKills <= 0) { // failstab!
        for(i=0; i<2; i+=1) {
            if (ownerPlayer.weapons[i] == WEAPON_MEDICHAIN and ownerPlayer.object.hp > 20) { // give some leniency to our spy mains
                ownerPlayer.object.hp -= 10;
            }    
            if (ownerPlayer.object.ability[i] == ABILITY_STABSPEED and ownerPlayer.object.meter[i] > 0) {
                ownerPlayer.object.meter[i] = 0;
            }
            /*
                if (ownerPlayer.depleteAbility[i] == ADEPLETE_MISS and numKills <= 0)
                {
                    ownerPlayer.object.meter[i] -= ownerPlayer.object.meterDrain[i];
                }
            */   
        }
    }
}
